
#[test]fn actual_shared_capture_denial_leaves_the_original_descriptor_empty(){
 let mut bank=Bank::new(false);let mut observer=|_|true;let mut native=NativeDecodeControl::new(1<<20,&mut observer);let mut frame=NativeReceivingEffect::default();let mut producer=OriginalEffectAuthority::new(Commands::<ArcMode>{source:bank.source.clone(),mode:PhantomData});let mut slots=Slots::<ArcMode>::default();let mut input=Some(73);let before=bank.wallet.lock().unwrap().fuel;let d=Slots::<ArcMode>::capture_demand().unwrap();let denied=complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,1,Command::Capture(&mut slots,&mut input)));assert_eq!(denied.result.unwrap(),RetainedCloneStep::Progress(Default::default()));assert_eq!(input,Some(73));assert!(slots.terminal_is_empty());assert_eq!(bank.wallet.lock().unwrap().fuel,before);assert_eq!(bank.wallet.lock().unwrap().spent,Default::default());assert!(producer.into_producer().is_ok());
}
#[test]fn actual_shared_capture_refuses_an_effect_without_its_original_source(){
 let mut slots=Slots::<ArcMode>::default();let mut input=Some(73);let d=Slots::<ArcMode>::capture_demand().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_depth:d.depth,..Default::default()};let mut actual=None;let mut effect=RetainedAllocationEffect::new(grant,2,&mut actual);let mut answer=std::mem::ManuallyDrop::new(None);let reply=OriginalEffectReply::borrow(&mut answer).unwrap();let complete=slots.capture(&mut input,&mut effect,reply).unwrap();drop(complete);assert!(answer.as_ref().unwrap().is_err());assert_eq!(input,Some(73));assert!(slots.terminal_is_empty());
}
